    21→    public static Entry init(List<RuleEntry> queue) {
    22→        Entry e = new Entry();
    23→        if (queue.size() > 0) {
    24→            e.start = queue.get(0).start;
    25→            RuleEntry lastOne = queue.get(queue.size() - 1);
    26→            e.lastPosition = lastOne.start + lastOne.length;
    27→        }
    28→        return e;
    29→    }
    30→
    31→    // e1을 e0에 붙여서 하나의 텀으로 만든다.
    32→    public static void merge(RuleEntry e0, RuleEntry e1, String type) {
    33→        e0.length = (e1.start + e1.length - e0.start);
    34→        e0.endOffset = e1.endOffset;
    35→        e0.type = type;
    36→    }
    37→
    38→    public static boolean isConnected(RuleEntry prevEntry, RuleEntry entry) {
    39→        return entry.start == prevEntry.start + prevEntry.length;
    40→    }
    41→
    42→    // e1을 e0에 붙여서 새로운 텀을 만든다.
    43→    public static RuleEntry mergeNewEntry(RuleEntry e0, RuleEntry e1, String type) {
    44→        RuleEntry e3 = e0.clone();
    45→        e3.length = (e1.start + e1.length - e0.start);
    46→        e3.endOffset = e1.endOffset;
    47→        e3.type = type;
    48→        return e3;
    49→    }
    50→
    51→    // e1, e2을 e0에 붙여서 새로운 텀을 만든다.
    52→    public static RuleEntry mergeNewEntry(RuleEntry e0, RuleEntry e1, RuleEntry e2, String type) {
    53→        RuleEntry e3 = mergeNewEntry(e0, e1, type);
    54→        e3.length = (e2.start + e2.length - e3.start);
    55→        e3.endOffset = e2.endOffset;
    56→        e3.type = type;
    57→        return e3;
    58→    }
    59→
    60→    public static void addEntry(List<RuleEntry> termList, CharVector ref, String type, PosTagProbEntry.PosTag posTag, int startOffset, int endOffset, SpaceDictionary spaceDictionary) {
    61→        if (type == FULL_STRING) {
    62→            // NOP
    63→        } else if (posTag == PosTagProbEntry.PosTag.N) {
    64→            type = HANGUL;
    65→        } else if (posTag == PosTagProbEntry.PosTag.DIGIT) {
    66→            type = NUMBER;
    67→        } else if (posTag == PosTagProbEntry.PosTag.ALPHA) {
    68→            type = ALPHA;
    69→        } else if (posTag == PosTagProbEntry.PosTag.SYMBOL) {
    70→            type = SYMBOL;
    71→        } else if (posTag == null || posTag == PosTagProbEntry.PosTag.UNK) {
    72→            type = UNCATEGORIZED;
    73→        }
    74→        if (type != FULL_STRING && spaceDictionary != null && spaceDictionary.containsKey(ref)) {
    75→            // 분리어가 발견되면
    76→            int offsetSt = startOffset;
    77→            CharSequence[] splits = spaceDictionary.get(ref);
    78→            logger.trace("SPLIT:{}{}", "", splits);
    79→            for (int sinx = 0, position = 0; sinx < splits.length; sinx++) {
    80→                int length = splits[sinx].length();
    81→                if (sinx > 0) {
    82→                    // 강제 분리를 위한 빈공백
    83→                    termList.add(new RuleEntry(ref.array(), position, 0,
    84→                            offsetSt + position, offsetSt + position, SYMBOL));
    85→                }
    86→                termList.add(new RuleEntry(ref.array(), ref.offset() + position, length,
    87→                        offsetSt + position, offsetSt + position + length, HANGUL));
    88→                position += length;
    89→            }
    90→        } else {
    91→            termList.add(new RuleEntry(ref.array(), ref.offset(), ref.length(),
    92→                    startOffset, endOffset, type));
    93→        }
    94→    }
    95→
    96→    public static int split(RuleEntry entry, List<RuleEntry> queue, int baseInx) {
    97→        // if (entry.length < 2) { return 0; }
    98→        logger.trace("split entry ({}) : {}~{}", entry, entry.start, entry.length);
    99→        String ptype = null;
   100→        String ctype = null;
   101→        int st = 0;
   102→        int addInx = 0;
   103→        int offsetStarts = entry.startOffset;
   104→        for (int inx = 0; inx < entry.length; inx++) {
   105→            char ch = entry.buf[entry.start + inx];
   106→            ctype = getType(ch);
   107→            if (ptype != null && ptype != ctype) {
   108→                RuleEntry entryClone = entry.clone();
   109→                entryClone.start = entry.start + st;
   110→                entryClone.length = inx - st;
   111→                entryClone.type = ptype;
   112→
   113→                entryClone.startOffset = offsetStarts + st;
   114→                entryClone.endOffset = offsetStarts + st + entryClone.length;
   115→                entryClone.modifiable = true;
   116→                logger.trace("add splited entry : ({}) : {}~{}", entryClone, entryClone.start, entryClone.length);
   117→                if (entryClone.type != WHITESPACE) {
   118→                    queue.add(baseInx + addInx, entryClone);
   119→                    addInx++;
   120→                }
   121→                // 엔트리 클로닝시 서브엔트리가 복제되는 버그 수정
   122→                if (inx > 0) {
   123→                    entryClone.subEntry = new ArrayList<>();
   124→                    entryClone.synonym = null;
   125→                }
   126→                st = inx;
   127→            }
   128→            ptype = ctype;
   129→        }
   130→        if (addInx >= 0 && st < entry.length) {
   131→            RuleEntry entryClone = entry.clone();
   132→            if (ptype == null) {
   133→                ptype = ctype;
   134→            }
   135→            entryClone.start = entry.start + st;
   136→            entryClone.length = entry.length - st;
   137→            entryClone.startOffset = offsetStarts + st;
   138→            entryClone.endOffset = offsetStarts + st + entryClone.length;
   139→            entryClone.type = ptype;
   140→            entryClone.subEntry = new ArrayList<>();
   141→            entryClone.synonym = null;
   142→            logger.trace("add splited entry : ({}) : {}~{}", entryClone, entryClone.start, entryClone.length);
   143→            queue.add(baseInx + addInx, entryClone);
   144→            addInx++;
   145→        }
   146→        return addInx;
   147→    }
   148→
   149→    protected static RuleEntry mergeQueueIndex(int qinx, int typeContinuous, List<RuleEntry> queue, List<RuleEntry> subQueue) {
   150→        int removeInx = qinx - typeContinuous;
   151→        if (removeInx < 0) {
   152→            removeInx = 0;
   153→            typeContinuous--;
   154→        }
   155→
   156→        if (queue.get(removeInx + typeContinuous - 1).type == SYMBOL) {
   157→            typeContinuous--;
   158→        }
   159→
   160→        if (typeContinuous == 1) {
   161→            logger.trace("queue has only one entry. so don't merge it");
   162→            return null;
   163→        }
   164→
   165→        logger.trace("queue[{}]={}", removeInx + typeContinuous - 1, queue.get(removeInx + typeContinuous - 1));
   166→
   167→        RuleEntry entry = queue.get(removeInx).clone();
   168→        logger.trace("ENTRY-CLONE:{}", entry);
   169→        // 클로닝 되기 때문에 동의어를 반드시 삭제 해 주어야 한다.
   170→        if (entry.type == UNIT_ALPHA) {
   171→            entry.synonym = null;
   172→        }
   173→        entry.length = 0;
   174→        entry.endOffset = entry.startOffset;
   175→        String type = entry.type;
   176→        RuleEntry subEntry;
   177→        RuleEntry nextEntry = null;
   178→        RuleEntry dummy = null;
   179→        for (; typeContinuous > 0; typeContinuous--) {
   180→            subEntry = queue.remove(removeInx);
   181→            logger.trace("pop entry:{}/{}:{}[{}~{}] / {}", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset, subEntry.synonym);
   182→            if (type != subEntry.type || (type == UNIT_ALPHA && subEntry.type == UNIT_ALPHA)) {
   183→                type = null;
   184→            }
   185→            int start = subEntry.start;
   186→            int length = subEntry.length;
   187→            int endOffset = subEntry.endOffset;
   188→            if (subQueue != null) {
   189→                if (subEntry.type == UNIT_ALPHA) {
   190→                    // 단위명이었지만 규칙에 의해 모델명으로 전환되는 경우.
   191→                    // 단위명과 숫자를 구분해준다.
   192→                    logger.trace("subList:{}{}", "", subEntry.subEntry);
   193→                    if (subEntry.subEntry.size() > 0) {
   194→                        int numIdx = 0;
   195→                        // 숫자 인덱스 검출
   196→                        for (RuleEntry e : subEntry.subEntry) {
   197→                            if (e.type == NUMBER || e.type == NUMBER_TRANS) {
   198→                                break;
   199→                            } else if (numIdx == subEntry.subEntry.size() - 1) {
   200→                                numIdx = 0;
   201→                            }
   202→                            numIdx++;
   203→                        }
   204→                        RuleEntry number = subEntry.subEntry.remove(numIdx);
   205→                        subQueue.add(number);
   206→                        subEntry.start += number.length;
   207→                        subEntry.length -= number.length;
   208→                        subEntry.startOffset += number.length;
   209→                        subEntry.type = ALPHA;
