   667→                                // 색인때에만
   668→                                // 모델명 중 숫자블럭 사이, 혹은 문자블럭 사이에 특수문자 가 있다면
   669→                                // 각각의 숫자, 혹은 문자 와 특수문자를 제거한 조합도 출력한다.
   670→                                int checkLevel = 0;
   671→                                if (nextEntry.startOffset == prevEntry.endOffset + 1) {
   672→                                    if (prevEntry.type == MODEL_NAME || prevEntry.type == ALPHANUM) {
   673→                                        if (nextEntry.type == ALPHA || nextEntry.type == NUMBER || nextEntry.type == ALPHANUM || nextEntry.type == MODEL_NAME) {
   674→                                            checkLevel = 2;
   675→                                        }
   676→                                    } else if (nextEntry.type == MODEL_NAME || nextEntry.type == ALPHANUM) {
   677→                                        if (prevEntry.type == ALPHA || prevEntry.type == NUMBER || prevEntry.type == ALPHANUM || prevEntry.type == MODEL_NAME) {
   678→                                            checkLevel = 2;
   679→                                        }
   680→                                    } else {
   681→                                        if (prevEntry.type == ALPHA || prevEntry.type == NUMBER) {
   682→                                            if (prevEntry.type == nextEntry.type) {
   683→                                                checkLevel = 3;
   684→                                            }
   685→                                        }
   686→                                    }
   687→                                }
   688→                                if (checkLevel == 2) {
   689→                                    // 앞단어 맨 뒤의 글자타입과 뒷단어 맨 첫번째의 글자타입이 같다면 수행
   690→                                    String lastCharTypeOfPrevEntry = getType(prevEntry.buf[prevEntry.start + prevEntry.length - 1]);
   691→                                    String firstCharTypeOfNextEntry = getType(nextEntry.buf[nextEntry.start]);
   692→                                    if (lastCharTypeOfPrevEntry == firstCharTypeOfNextEntry) {
   693→                                        // 같은 타입만 잘라낸다.
   694→                                        // 둘중 하나가 모델명 이었다면, 같은 타입의 부분만 잘라 내야 한다.
   695→                                        int newPrevEntryLength = 0;
   696→                                        for (int sinx = prevEntry.length; sinx > 0; sinx--) {
   697→                                            if (getType(prevEntry.buf[prevEntry.start + sinx - 1]) == lastCharTypeOfPrevEntry) {
   698→                                                newPrevEntryLength++;
   699→                                            } else {
   700→                                                break;
   701→                                            }
   702→                                        }
   703→                                        // 조정된 길이로 prevEntry 새로 셋팅.
   704→                                        RuleEntry tmpEntry = prevEntry.clone();
   705→                                        tmpEntry.start += (prevEntry.length - newPrevEntryLength);
   706→                                        tmpEntry.startOffset += (prevEntry.length - newPrevEntryLength);
   707→                                        tmpEntry.length = newPrevEntryLength;
   708→                                        tmpEntry.endOffset = tmpEntry.startOffset + newPrevEntryLength;
   709→                                        tmpEntry.type = lastCharTypeOfPrevEntry;
   710→                                        prevEntry = tmpEntry;
   711→
   712→                                        int newNextEntryLength = 0;
   713→                                        for (int sinx = 0; sinx < nextEntry.length; sinx++) {
   714→                                            if (getType(nextEntry.buf[nextEntry.start + sinx]) == firstCharTypeOfNextEntry) {
   715→                                                newNextEntryLength++;
   716→                                            } else {
   717→                                                break;
   718→                                            }
   719→                                        }
   720→                                        // 조정된 길이로 nextEntry 새로 셋팅.
   721→                                        RuleEntry tmpEntry2 = nextEntry.clone();
   722→                                        tmpEntry2.length = newNextEntryLength;
   723→                                        tmpEntry2.endOffset = tmpEntry2.startOffset + newNextEntryLength;
   724→                                        tmpEntry2.type = firstCharTypeOfNextEntry;
   725→                                        nextEntry = tmpEntry2;
   726→                                        checkLevel = 3;
   727→                                    }
   728→                                }
   729→                                if (checkLevel == 3) {
   730→                                    // 원본변형이 일어나기 때문에 버퍼는 따로 잡아 주어야 한다.
   731→                                    RuleEntry clone = prevEntry.clone();
   732→                                    char[] buf = new char[prevEntry.length + nextEntry.length];
   733→                                    System.arraycopy(prevEntry.buf, prevEntry.start, buf, 0, prevEntry.length);
   734→                                    System.arraycopy(nextEntry.buf, nextEntry.start, buf, prevEntry.length, nextEntry.length);
   735→                                    clone.buf = buf;
   736→                                    clone.start = 0;
   737→                                    clone.length = buf.length;
   738→                                    clone.startOffset = prevEntry.startOffset;
   739→                                    clone.endOffset = nextEntry.endOffset;
   740→                                    logger.trace("TRANS-MERGE:{} / {} / {}", clone, currentEntry, prevEntry);
   741→                                    tmpList.add(clone);
   742→                                }
   743→                            }
   744→                        }
   745→                    }
   746→                    // 개별 특수문자는 모두 제거한다.
   747→                    subQueue.remove(inx);
   748→                    inx--;
   749→                } else if (currentEntry.type == UNIT_ALPHA) {
   750→                    // 단위명이었지만 규칙에 의해 모델명으로 전환되는 경우.
   751→                    // 단위명과 숫자를 구분해준다.
   752→                    logger.trace("subList:{}{}", "", currentEntry.subEntry);
   753→                    if (currentEntry.subEntry != null && currentEntry.subEntry.size() > 0) {
   754→                        RuleEntry e1 = currentEntry.subEntry.remove(0);
   755→                        tmpList.add(e1);
   756→                        currentEntry.start += e1.length;
   757→                        currentEntry.length -= e1.length;
   758→                        currentEntry.type = ALPHA;
   759→                    } else {
   760→                        currentEntry.type = ALPHANUM;
   761→                    }
   762→                    currentEntry.synonym = null;
   763→                } else if (currentEntry.type == ALPHA) {
   764→                    // 강제분해 등으로 붙지 못한 영문자 끼리 이어준다.
   765→                    if (inx + 1 < subQueue.size()) {
   766→                        RuleEntry e1 = subQueue.get(inx + 1);
   767→                        if (e1.startOffset == currentEntry.endOffset + 1 && e1.type == ALPHA) {
   768→                            currentEntry.length += e1.length;
   769→                            currentEntry.endOffset = e1.endOffset;
   770→                            subQueue.remove(inx + 1);
   771→                        }
   772→                    }
   773→                }
   774→            }
   775→
   776→            logger.trace("subQueue : {}", subQueue);
   777→
   778→            if (subQueue.size() > 2) {
   779→                RuleEntry currentEntry = subQueue.get(0);
   780→                RuleEntry nextEntry = subQueue.get(1);
   781→                logger.trace("TERM:{}/{}", nextEntry.start, nextEntry.length);
   782→                String finalType = getType(nextEntry.buf[nextEntry.start + nextEntry.length - 1]);
   783→                // 모델명 맨 앞의 두 바이트가 타입이 틀리고 뒤에 기호가 나오면 붙여준다.
   784→                if (nextEntry.start == currentEntry.start + currentEntry.length &&
   785→                        currentEntry.length == 1 && nextEntry.length == 1 && finalType == SYMBOL
   786→                        && ((currentEntry.type == NUMBER && nextEntry.type == ALPHA)
   787→                        || (currentEntry.type == ALPHA && nextEntry.type == NUMBER))) {
   788→                    subQueue.remove(1);
   789→                    currentEntry.length += nextEntry.length;
   790→                    currentEntry.endOffset = currentEntry.startOffset + currentEntry.length + nextEntry.length;
   791→                    currentEntry.type = MODEL_NAME;
   792→                }
   793→            }
   794→
   795→            if (!option.useForQuery()) {
   796→                // 추가 텀 추출
   797→                exportByTriGram(subQueue, tmpList);
   798→                // 단위명 추가 텀 추출
   799→                exportUnitGram(subQueue, tmpList, unitDictionary);
   800→            }
   801→
   802→            if (tmpList.size() > 0) {
   803→                subQueue.addAll(tmpList);
   804→            }
   805→            ////////////////////////////////////////////////////////////////////////////////
   806→            Collections.sort(subQueue);
   807→        }
   808→    }
