    10→import java.util.Collections;
    11→import java.util.List;
    12→
    13→import static com.danawa.search.analysis.product.ProductNameTokenizer.*;
    14→import static com.danawa.search.analysis.product.ProductNameTokenizer.NUMBER_TRANS;
    15→
    16→public class RuleOne extends Rule {
    17→
    18→    public RuleOne(Entry entry, boolean fullExtract, AnalyzerOption option, SpaceDictionary spaceDictionary,
    19→                   SetDictionary stopDictionary, SetDictionary userDictionary, SetDictionary unitDictionary,
    20→                   CompoundDictionary compoundDictionary, KoreanWordExtractor extractor) {
    21→        super(entry, fullExtract, option);
    22→        this.spaceDictionary = spaceDictionary;
    23→        this.stopDictionary = stopDictionary;
    24→        this.userDictionary = userDictionary;
    25→        this.unitDictionary = unitDictionary;
    26→        this.compoundDictionary = compoundDictionary;
    27→        this.extractor = extractor;
    28→    }
    29→
    30→    @Override
    31→    public void apply(List<RuleEntry> queue) {
    32→        CharVector cvTmp = new CharVector();
    33→        cvTmp.ignoreCase();
    34→        CharVector eTerm;
    35→        RuleEntry currentEntry, nextEntry, prevEntry;
    36→        ////////////////////////////////////////////////////////////////////////////////
    37→        // 규칙분류 시작.
    38→        Collections.sort(queue);
    39→
    40→        for (int qinx = 0; qinx < queue.size(); qinx++) {
    41→            currentEntry = queue.get(qinx);
    42→            if (isFullStringEntry(currentEntry)) {
    43→                continue;
    44→            }
    45→            if (currentEntry.length == 0) {
    46→                setDisableEntry(queue, currentEntry, qinx);
    47→                continue;
    48→            }
    49→
    50→            if (currentEntry.type == UNCATEGORIZED) {
    51→                if (!userDictionary.contains(currentEntry.makeTerm(null))) {
    52→                    RuleEntry entry = queue.remove(qinx);
    53→                    Entry.split(entry, queue, qinx);
    54→                    currentEntry = queue.get(qinx);
    55→                } else {
    56→                    currentEntry.type = HANGUL;
    57→                }
    58→            }
    59→            cvTmp.init(currentEntry.buf, currentEntry.start, currentEntry.length);
    60→
    61→            if (fullExtract) {
    62→                qinx = ruleFullExtract(queue, cvTmp, currentEntry, qinx);
    63→            }
    64→            currentEntry = queue.get(qinx);
    65→
    66→            // 한글인 경우 (사전에 등록된 단어 중) 숫자로 시작하고 단위명으로 끝나는것을 분리한다.
    67→            if (currentEntry.type == HANGUL && currentEntry.modifiable) {
    68→                if (getType(currentEntry.buf[currentEntry.start]) == NUMBER) {
    69→                    int numInx = 1;
    70→                    boolean numberChar;
    71→                    boolean numberTrans = false;
    72→                    for (; numInx < currentEntry.length; numInx++) {
    73→                        char ch = currentEntry.buf[currentEntry.start + numInx];
    74→                        numberChar = containsChar(AVAIL_SYMBOLS_INNUMBER, ch);
    75→                        if (numberChar) {
    76→                            numberTrans = true;
    77→                        }
    78→                        if (getType(ch) != NUMBER && !numberChar) {
    79→                            break;
    80→                        }
    81→                    }
    82→                    CharVector unitCv = new CharVector(currentEntry.buf, currentEntry.start + numInx, currentEntry.length - numInx);
    83→                    if (unitDictionary != null && unitDictionary.contains(unitCv)) {
    84→                        qinx = ruleUnitDict(queue, currentEntry, qinx, numInx, numberTrans, unitCv);
    85→                        continue;
    86→                    }
    87→                } else {
    88→                    // 3글자 이하 단어 중 앞 또는 뒤에 인접한 단어인 경우
    89→                    // 사용자 단어에 포함되지 않은 것들 중에서 원래 타입으로 환산한다.
    90→                    if (currentEntry.length <= 3 && currentEntry.modifiable) {
    91→                        eTerm = currentEntry.makeTerm(null);
    92→                        boolean joinable = false;
    93→                        if (userDictionary != null && !userDictionary.contains(eTerm)) {
    94→                            // 영숫자 인 경우에만.
    95→                            if (isAlphaNum(eTerm)) {
    96→                                if (qinx > 0) {
    97→                                    prevEntry = queue.get(qinx - 1);
    98→                                    joinable = currentEntry.start == prevEntry.start + prevEntry.length && (prevEntry.type == ALPHA || prevEntry.type == NUMBER || prevEntry.type == SYMBOL);
    99→                                }
   100→
   101→                                if (!joinable && qinx + 1 < queue.size()) {
   102→                                    nextEntry = queue.get(qinx + 1);
   103→                                    joinable = nextEntry.start == currentEntry.start + currentEntry.length && (nextEntry.type == ALPHA || nextEntry.type == NUMBER || nextEntry.type == SYMBOL);
   104→                                }
   105→                                if (joinable) {
   106→                                    queue.remove(qinx);
   107→                                    Entry.split(currentEntry, queue, qinx);
   108→                                }
   109→                                continue;
   110→                            }
   111→                        }
   112→                        String eType = getTermType(eTerm);
   113→                        if (eType == ALPHA) {
   114→                            currentEntry.type = ALPHA;
   115→                        } else if (eType == NUMBER) {
   116→                            logger.trace("NUMBER FOUND:{}", currentEntry);
   117→                            currentEntry.type = NUMBER;
   118→                        } else if (eType == ASCII || eType == ALPHANUM) {
   119→                            currentEntry.type = MODEL_NAME;
   120→                        }
   121→                    }
   122→                }
   123→            }
   124→            if (qinx + 1 < queue.size()) {
   125→                prevEntry = queue.get(qinx + 1);
   126→
   127→                logger.trace("currentEntry0:{}/prevEntry:{} {}:{}", currentEntry, prevEntry, currentEntry.endOffset, prevEntry.startOffset);
   128→                qinx = ruleNumberEntry(queue, currentEntry, prevEntry, qinx);
   129→            }
   130→        }
   131→        ////////////////////////////////////////////////////////////////////////////////
   132→        logger.trace("1st process complete / queue:{}", queue);
   133→    }
   134→
   135→    private int ruleFullExtract(List<RuleEntry> queue, CharVector cvTmp, RuleEntry currentEntry, int qinx) {
   136→        RuleEntry prevEntry;
   137→        // extractor 는 타입이 다른 엔트리 에 대해서 체크하지 못하므로
   138→        // 엔트리들을 합쳐서 복합어/사용자 사전에 체크해 본다
   139→        // 최대 10개 엔트리까지 체크
   140→        String ctype = getType(currentEntry.buf[currentEntry.start + currentEntry.length - 1]);
   141→        for (int linx = 10; linx >= 1; linx--) {
   142→            int passFlag = 0;
   143→            char[] tmpBuf = currentEntry.buf;
   144→            int tmpSt = currentEntry.start;
   145→            int tmpEd;
   146→
   147→            // 합쳐질 단어들은 사이에 공백이 없고 묶은뒤 앞뒤로
   148→            // 공백이 있는경우에만 합치도록 한다.
   149→            // 로직의 유연화를 위해 루프기반 로직으로 변경 (2020.1.23)
   150→            if (queue.size() > qinx + linx) {
   151→                prevEntry = queue.get(qinx + linx);
   152→                if (prevEntry.buf == tmpBuf && prevEntry.length > 0 && prevEntry.type != FULL_STRING) {
   153→                    tmpEd = prevEntry.start + prevEntry.length;
   154→                    char tmpStCh = (tmpSt > 0) ? tmpBuf[tmpSt - 1] : 0;
   155→                    char tmpEdCh = (tmpEd < entry.lastPosition) ? tmpBuf[tmpEd] : 0;
   156→                    String tmpStCType = getType(tmpStCh);
   157→                    String tmpEdCType = getType(tmpEdCh);
   158→                    passFlag = ruleCombineEntry(queue, currentEntry, qinx, ctype, linx, passFlag, tmpSt, tmpEd, tmpStCh, tmpEdCh, tmpStCType, tmpEdCType);
   159→                    ctype = tmpEdCType;
   160→                }
   161→            }
   162→
   163→            if (passFlag != 0) {
   164→                prevEntry = queue.get(qinx + linx);
   165→                cvTmp.init(currentEntry.buf, currentEntry.start, prevEntry.start + prevEntry.length - currentEntry.start);
   166→                passFlag = 0;
   167→
   168→                // 통합사전 체크는 상대적으로 느리기 때문에 개별사전부터 체크한 후 passFlag 로 나눈다.
   169→                if (spaceDictionary != null && spaceDictionary.containsKey(cvTmp)) {
   170→                    // 색인 시 분리어에서 단위명이 검출되면 분리어 처리하지 않도록 한다
   171→                    CharVector currentTerm = new CharVector();
   172→                    currentTerm.init(currentEntry.buf, currentEntry.start, currentEntry.length);
   173→
   174→                    CharVector prevTerm = new CharVector();
   175→                    prevTerm.init(prevEntry.buf, prevEntry.start, prevEntry.length);
   176→
   177→                    if(!unitDictionary.contains(currentTerm) && !unitDictionary.contains(prevTerm)){
   178→                        passFlag = 1;
   179→                    }
   180→                } else if ((stopDictionary != null && stopDictionary.contains(cvTmp))) {
   181→                    passFlag = 2;
   182→                } else if (containsDictionary(cvTmp)) {
   183→                    passFlag = 3;
   184→                }
   185→
   186→                if (passFlag != 0) {
   187→                    Entry.merge(currentEntry, prevEntry, HANGUL);
   188→                    if (qinx + linx >= qinx) {
   189→                        queue.subList(qinx, qinx + linx + 1).clear();
   190→                    }
   191→                    if (passFlag == 1) {
   192→                        qinx = ruleSpaceDict(queue, cvTmp, currentEntry, qinx);
   193→                    } else if (passFlag == 2) {
   194→                        ruleStopDict(queue, currentEntry, qinx);
   195→                    } else {
   196→                        queue.add(qinx, currentEntry);
   197→                    }
   198→                    break;
   199→                }
   200→            }
   201→        }
   202→        return qinx;
   203→    }
   204→
   205→    private int ruleUnitDict(List<RuleEntry> queue, RuleEntry currentEntry, int qinx, int numInx, boolean numberTrans, CharVector unitCv) {
   206→        RuleEntry prevEntry;
   207→        prevEntry = currentEntry.clone();
   208→        currentEntry.length = numInx;
   209→        currentEntry.endOffset = currentEntry.startOffset + currentEntry.length;
   210→        logger.trace("NUMBER FOUND:{} / {}", currentEntry, prevEntry);
   211→        if (numberTrans) {
   212→            currentEntry.type = NUMBER_TRANS;
   213→        } else {
   214→            currentEntry.type = NUMBER;
   215→        }
   216→        prevEntry.start += numInx;
   217→        prevEntry.length -= numInx;
   218→        prevEntry.type = getTermType(unitCv);
   219→        queue.add(qinx + 1, prevEntry);
   220→        qinx++;
   221→        return qinx;
   222→    }
   223→
   224→    private int ruleCombineEntry(List<RuleEntry> queue, RuleEntry currentEntry, int qinx, String ctype, int linx, int passFlag, int tmpSt, int tmpEd, char tmpStCh, char tmpEdCh, String tmpStCType, String tmpEdCType) {
   225→        RuleEntry nextEntry;
   226→        RuleEntry prevEntry;
   227→        if ((tmpSt == 0 || (tmpStCh != 0 && (tmpStCh == ' ' || tmpStCType != ctype))) &&
   228→                (tmpEd == entry.lastPosition || (tmpEdCh != 0 && (tmpEdCh == ' ' || tmpEdCType != ctype)))) {
   229→            passFlag = 1;
   230→            prevEntry = currentEntry;
   231→            for (int tinx = 0; tinx < linx; tinx++) {
   232→                nextEntry = queue.get(qinx + tinx + 1);
   233→                if (nextEntry.length == 0 || nextEntry.type == FULL_STRING || nextEntry.start != prevEntry.start + prevEntry.length) {
   234→                    passFlag = 0;
   235→                    break;
   236→                }
   237→                prevEntry = nextEntry;
   238→            }
   239→        }
   240→        return passFlag;
   241→    }
   242→
   243→    private void ruleStopDict(List<RuleEntry> queue, RuleEntry currentEntry, int qinx) {
   244→        // 금칙어 규칙은 아래의 경우 (사용자,동의어,브랜드,메이커) 와 다르게
   245→        // 통합시, 분리시 동시체크를 할 필요가 없으므로 다른 로직을 적용
   246→        currentEntry.modifiable = false;
   247→        queue.add(qinx, currentEntry);
   248→    }
   249→
   250→    private int ruleSpaceDict(List<RuleEntry> queue, CharVector cvTmp, RuleEntry currentEntry, int qinx) {
   251→        RuleEntry prevEntry;
   252→        CharSequence[] splits = spaceDictionary.get(cvTmp);
   253→        int start = currentEntry.start;
   254→        int startOffset = currentEntry.startOffset;
   255→        for (int sinx = 0; sinx < splits.length; sinx++) {
   256→            CharSequence split = splits[sinx];
   257→            prevEntry = new RuleEntry(currentEntry.buf, start, split.length(),
   258→                    startOffset, startOffset + split.length(), HANGUL);
   259→            ruleStopDict(queue, prevEntry, qinx + sinx);
   260→            start += prevEntry.length;
   261→            startOffset += prevEntry.length;
   262→        }
   263→        qinx += splits.length - 1;
   264→        return qinx;
   265→    }
   266→
   267→    private int ruleNumberEntry(List<RuleEntry> queue, RuleEntry currentEntry, RuleEntry prevEntry, int qinx) {
   268→        if ((currentEntry.type == NUMBER || currentEntry.type == NUMBER_TRANS)
   269→                && prevEntry.type == NUMBER && currentEntry.endOffset != prevEntry.startOffset) {
   270→            char c = currentEntry.buf[currentEntry.start + currentEntry.length];
   271→            if (logger.isTraceEnabled()) {
   272→                logger.trace("c:{} / type:{} / contains:{}", c, getType(c), containsChar(AVAIL_SYMBOLS_INNUMBER, c));
   273→            }
   274→            if (getType(c) == SYMBOL && containsChar(AVAIL_SYMBOLS_INNUMBER, c)) {
   275→                queue.remove(qinx + 1);
   276→                currentEntry.length += 1 + prevEntry.length;
   277→                currentEntry.endOffset = prevEntry.endOffset;
   278→                currentEntry.type = NUMBER_TRANS;
   279→                qinx--;
   280→            }
   281→        }
   282→        return qinx;
   283→    }
   284→
   285→    private void setDisableEntry(List<RuleEntry> queue, RuleEntry currentEntry, int qinx) {
