package com.danawa.search.analysis.product.rule;

import com.danawa.search.analysis.dict.CompoundDictionary;
import com.danawa.search.analysis.dict.SetDictionary;
import com.danawa.search.analysis.dict.SpaceDictionary;
import com.danawa.search.analysis.korean.KoreanWordExtractor;
import com.danawa.search.analysis.product.AnalyzerOption;
import com.danawa.util.CharVector;

import java.util.Collections;
import java.util.List;

import static com.danawa.search.analysis.product.ProductNameTokenizer.*;
import static com.danawa.search.analysis.product.ProductNameTokenizer.NUMBER_TRANS;

public class RuleOne extends Rule {

    public RuleOne(Entry entry, boolean fullExtract, AnalyzerOption option, SpaceDictionary spaceDictionary,
                   SetDictionary stopDictionary, SetDictionary userDictionary, SetDictionary unitDictionary,
                   CompoundDictionary compoundDictionary, KoreanWordExtractor extractor) {
        super(entry, fullExtract, option);
        this.spaceDictionary = spaceDictionary;
        this.stopDictionary = stopDictionary;
        this.userDictionary = userDictionary;
        this.unitDictionary = unitDictionary;
        this.compoundDictionary = compoundDictionary;
        this.extractor = extractor;
    }

    @Override
    public void apply(List<RuleEntry> queue) {
        CharVector cvTmp = new CharVector();
        cvTmp.ignoreCase();
        CharVector eTerm;
        RuleEntry currentEntry, nextEntry, prevEntry;
        ////////////////////////////////////////////////////////////////////////////////
        // 규칙분류 시작.
        Collections.sort(queue);

        for (int qinx = 0; qinx < queue.size(); qinx++) {
            currentEntry = queue.get(qinx);
            if (isFullStringEntry(currentEntry)) {
                continue;
            }
            if (currentEntry.length == 0) {
                setDisableEntry(queue, currentEntry, qinx);
                continue;
            }

            if (currentEntry.type == UNCATEGORIZED) {
                if (!userDictionary.contains(currentEntry.makeTerm(null))) {
                    RuleEntry entry = queue.remove(qinx);
                    Entry.split(entry, queue, qinx);
                    currentEntry = queue.get(qinx);
                } else {
                    currentEntry.type = HANGUL;
                }
            }
            cvTmp.init(currentEntry.buf, currentEntry.start, currentEntry.length);

            if (fullExtract) {
                qinx = ruleFullExtract(queue, cvTmp, currentEntry, qinx);
            }
            currentEntry = queue.get(qinx);

            // 한글인 경우 (사전에 등록된 단어 중) 숫자로 시작하고 단위명으로 끝나는것을 분리한다.
            if (currentEntry.type == HANGUL && currentEntry.modifiable) {
                if (getType(currentEntry.buf[currentEntry.start]) == NUMBER) {
                    int numInx = 1;
                    boolean numberChar;
                    boolean numberTrans = false;
                    for (; numInx < currentEntry.length; numInx++) {
                        char ch = currentEntry.buf[currentEntry.start + numInx];
                        numberChar = containsChar(AVAIL_SYMBOLS_INNUMBER, ch);
                        if (numberChar) {
                            numberTrans = true;
                        }
                        if (getType(ch) != NUMBER && !numberChar) {
                            break;
                        }
                    }
                    CharVector unitCv = new CharVector(currentEntry.buf, currentEntry.start + numInx, currentEntry.length - numInx);
                    if (unitDictionary != null && unitDictionary.contains(unitCv)) {
                        qinx = ruleUnitDict(queue, currentEntry, qinx, numInx, numberTrans, unitCv);
                        continue;
                    }
                } else {
                    // 3글자 이하 단어 중 앞 또는 뒤에 인접한 단어인 경우
                    // 사용자 단어에 포함되지 않은 것들 중에서 원래 타입으로 환산한다.
                    if (currentEntry.length <= 3 && currentEntry.modifiable) {
                        eTerm = currentEntry.makeTerm(null);
                        boolean joinable = false;
                        if (userDictionary != null && !userDictionary.contains(eTerm)) {
                            // 영숫자 인 경우에만.
                            if (isAlphaNum(eTerm)) {
                                if (qinx > 0) {
                                    prevEntry = queue.get(qinx - 1);
                                    joinable = currentEntry.start == prevEntry.start + prevEntry.length && (prevEntry.type == ALPHA || prevEntry.type == NUMBER || prevEntry.type == SYMBOL);
                                }

                                if (!joinable && qinx + 1 < queue.size()) {
                                    nextEntry = queue.get(qinx + 1);
                                    joinable = nextEntry.start == currentEntry.start + currentEntry.length && (nextEntry.type == ALPHA || nextEntry.type == NUMBER || nextEntry.type == SYMBOL);
                                }
                                if (joinable) {
                                    queue.remove(qinx);
                                    Entry.split(currentEntry, queue, qinx);
                                }
                                continue;
                            }
                        }
                        String eType = getTermType(eTerm);
                        if (eType == ALPHA) {
                            currentEntry.type = ALPHA;
                        } else if (eType == NUMBER) {
                            logger.trace("NUMBER FOUND:{}", currentEntry);
                            currentEntry.type = NUMBER;
                        } else if (eType == ASCII || eType == ALPHANUM) {
                            currentEntry.type = MODEL_NAME;
                        }
                    }
                }
            }
            if (qinx + 1 < queue.size()) {
                prevEntry = queue.get(qinx + 1);

                logger.trace("currentEntry0:{}/prevEntry:{} {}:{}", currentEntry, prevEntry, currentEntry.endOffset, prevEntry.startOffset);
                qinx = ruleNumberEntry(queue, currentEntry, prevEntry, qinx);
            }
        }
        ////////////////////////////////////////////////////////////////////////////////
        logger.trace("1st process complete / queue:{}", queue);
    }

    private int ruleFullExtract(List<RuleEntry> queue, CharVector cvTmp, RuleEntry currentEntry, int qinx) {
        RuleEntry prevEntry;
        // extractor 는 타입이 다른 엔트리 에 대해서 체크하지 못하므로
        // 엔트리들을 합쳐서 복합어/사용자 사전에 체크해 본다
        // 최대 10개 엔트리까지 체크
        String ctype = getType(currentEntry.buf[currentEntry.start + currentEntry.length - 1]);
        for (int linx = 10; linx >= 1; linx--) {
            int passFlag = 0;
            char[] tmpBuf = currentEntry.buf;
            int tmpSt = currentEntry.start;
            int tmpEd;

            // 합쳐질 단어들은 사이에 공백이 없고 묶은뒤 앞뒤로
            // 공백이 있는경우에만 합치도록 한다.
            // 로직의 유연화를 위해 루프기반 로직으로 변경 (2020.1.23)
            if (queue.size() > qinx + linx) {
                prevEntry = queue.get(qinx + linx);
                if (prevEntry.buf == tmpBuf && prevEntry.length > 0 && prevEntry.type != FULL_STRING) {
                    tmpEd = prevEntry.start + prevEntry.length;
                    char tmpStCh = (tmpSt > 0) ? tmpBuf[tmpSt - 1] : 0;
                    char tmpEdCh = (tmpEd < entry.lastPosition) ? tmpBuf[tmpEd] : 0;
                    String tmpStCType = getType(tmpStCh);
                    String tmpEdCType = getType(tmpEdCh);
                    passFlag = ruleCombineEntry(queue, currentEntry, qinx, ctype, linx, passFlag, tmpSt, tmpEd, tmpStCh, tmpEdCh, tmpStCType, tmpEdCType);
                    ctype = tmpEdCType;
                }
            }

            if (passFlag != 0) {
                prevEntry = queue.get(qinx + linx);
                cvTmp.init(currentEntry.buf, currentEntry.start, prevEntry.start + prevEntry.length - currentEntry.start);
                passFlag = 0;

                // 통합사전 체크는 상대적으로 느리기 때문에 개별사전부터 체크한 후 passFlag 로 나눈다.
                if (spaceDictionary != null && spaceDictionary.containsKey(cvTmp)) {
                    // 색인 시 분리어에서 단위명이 검출되면 분리어 처리하지 않도록 한다
                    CharVector currentTerm = new CharVector();
                    currentTerm.init(currentEntry.buf, currentEntry.start, currentEntry.length);

                    CharVector prevTerm = new CharVector();
                    prevTerm.init(prevEntry.buf, prevEntry.start, prevEntry.length);

                    if(!unitDictionary.contains(currentTerm) && !unitDictionary.contains(prevTerm)){
                        passFlag = 1;
                    }
                } else if ((stopDictionary != null && stopDictionary.contains(cvTmp))) {
                    passFlag = 2;
                } else if (containsDictionary(cvTmp)) {
                    passFlag = 3;
                }

                if (passFlag != 0) {
                    Entry.merge(currentEntry, prevEntry, HANGUL);
                    if (qinx + linx >= qinx) {
                        queue.subList(qinx, qinx + linx + 1).clear();
                    }
                    if (passFlag == 1) {
                        qinx = ruleSpaceDict(queue, cvTmp, currentEntry, qinx);
                    } else if (passFlag == 2) {
                        ruleStopDict(queue, currentEntry, qinx);
                    } else {
                        queue.add(qinx, currentEntry);
                    }
                    break;
                }
            }
        }
        return qinx;
    }

    private int ruleUnitDict(List<RuleEntry> queue, RuleEntry currentEntry, int qinx, int numInx, boolean numberTrans, CharVector unitCv) {
        RuleEntry prevEntry;
        prevEntry = currentEntry.clone();
        currentEntry.length = numInx;
        currentEntry.endOffset = currentEntry.startOffset + currentEntry.length;
        logger.trace("NUMBER FOUND:{} / {}", currentEntry, prevEntry);
        if (numberTrans) {
            currentEntry.type = NUMBER_TRANS;
        } else {
            currentEntry.type = NUMBER;
        }
        prevEntry.start += numInx;
        prevEntry.length -= numInx;
        prevEntry.type = getTermType(unitCv);
        queue.add(qinx + 1, prevEntry);
        qinx++;
        return qinx;
    }

    private int ruleCombineEntry(List<RuleEntry> queue, RuleEntry currentEntry, int qinx, String ctype, int linx, int passFlag, int tmpSt, int tmpEd, char tmpStCh, char tmpEdCh, String tmpStCType, String tmpEdCType) {
        RuleEntry nextEntry;
        RuleEntry prevEntry;
        if ((tmpSt == 0 || (tmpStCh != 0 && (tmpStCh == ' ' || tmpStCType != ctype))) &&
                (tmpEd == entry.lastPosition || (tmpEdCh != 0 && (tmpEdCh == ' ' || tmpEdCType != ctype)))) {
            passFlag = 1;
            prevEntry = currentEntry;
            for (int tinx = 0; tinx < linx; tinx++) {
                nextEntry = queue.get(qinx + tinx + 1);
                if (nextEntry.length == 0 || nextEntry.type == FULL_STRING || nextEntry.start != prevEntry.start + prevEntry.length) {
                    passFlag = 0;
                    break;
                }
                prevEntry = nextEntry;
            }
        }
        return passFlag;
    }

    private void ruleStopDict(List<RuleEntry> queue, RuleEntry currentEntry, int qinx) {
        // 금칙어 규칙은 아래의 경우 (사용자,동의어,브랜드,메이커) 와 다르게
        // 통합시, 분리시 동시체크를 할 필요가 없으므로 다른 로직을 적용
        currentEntry.modifiable = false;
        queue.add(qinx, currentEntry);
    }

    private int ruleSpaceDict(List<RuleEntry> queue, CharVector cvTmp, RuleEntry currentEntry, int qinx) {
        RuleEntry prevEntry;
        CharSequence[] splits = spaceDictionary.get(cvTmp);
        int start = currentEntry.start;
        int startOffset = currentEntry.startOffset;
        for (int sinx = 0; sinx < splits.length; sinx++) {
            CharSequence split = splits[sinx];
            prevEntry = new RuleEntry(currentEntry.buf, start, split.length(),
                    startOffset, startOffset + split.length(), HANGUL);
            ruleStopDict(queue, prevEntry, qinx + sinx);
            start += prevEntry.length;
            startOffset += prevEntry.length;
        }
        qinx += splits.length - 1;
        return qinx;
    }

    private int ruleNumberEntry(List<RuleEntry> queue, RuleEntry currentEntry, RuleEntry prevEntry, int qinx) {
        if ((currentEntry.type == NUMBER || currentEntry.type == NUMBER_TRANS)
                && prevEntry.type == NUMBER && currentEntry.endOffset != prevEntry.startOffset) {
            char c = currentEntry.buf[currentEntry.start + currentEntry.length];
            if (logger.isTraceEnabled()) {
                logger.trace("c:{} / type:{} / contains:{}", c, getType(c), containsChar(AVAIL_SYMBOLS_INNUMBER, c));
            }
            if (getType(c) == SYMBOL && containsChar(AVAIL_SYMBOLS_INNUMBER, c)) {
                queue.remove(qinx + 1);
                currentEntry.length += 1 + prevEntry.length;
                currentEntry.endOffset = prevEntry.endOffset;
                currentEntry.type = NUMBER_TRANS;
                qinx--;
            }
        }
        return qinx;
    }

    private void setDisableEntry(List<RuleEntry> queue, RuleEntry currentEntry, int qinx) {
        currentEntry.modifiable = false;
        if (qinx > 0 && qinx + 1 < queue.size()) {
            queue.get(qinx - 1).modifiable = false;
            queue.get(qinx + 1).modifiable = false;
        }
    }
}

