package com.danawa.search.analysis.product.rule;

import com.danawa.search.analysis.dict.CompoundDictionary;
import com.danawa.search.analysis.dict.SetDictionary;
import com.danawa.search.analysis.product.AnalyzerOption;
import com.danawa.util.CharVector;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static com.danawa.search.analysis.product.ProductNameTokenizer.*;

public class RuleFive extends Rule {
    public RuleFive(Entry entry, boolean fullExtract, AnalyzerOption option, SetDictionary userDictionary,
                    CompoundDictionary compoundDictionary) {
        super(entry, fullExtract, option);
        this.userDictionary = userDictionary;
        this.compoundDictionary = compoundDictionary;
    }

    @Override
    public void apply(List<RuleEntry> queue) {
        RuleEntry nextEntry;
        RuleEntry prevEntry;
        RuleEntry currentEntry;

        // 5차 가공, 예외규칙을 적용하고, 모델명, 단위명을 제외한 모든 텀을 합쳐서 내보낸다.
        // 특수문자 포함. 단 필요없는 특수문자는 버린다.
        for (int qinx = 0; qinx < queue.size(); qinx++) {
            currentEntry = queue.get(qinx);
            if (isFullStringEntry(currentEntry) || userDictionary.contains(currentEntry.makeTerm(null))) {
                continue;
            }

            // 길이가 0인 겨우 제거한다. (구분자)
            if (currentEntry.length == 0) {
                qinx = removeQueue(queue, qinx);
                continue;
            }

            // 올 수 없는 특수문자는 제외시킨다.
            if (isNotAvailSymbol(currentEntry)) {
                qinx = removeQueue(queue, qinx);
                continue;
            }

            // Symbol Entry에 대해 처리
            if(isSymbolEntry(currentEntry)){
                // 맨 앞의 독립 기호는 제거
                if (isHeadIndex(queue, qinx)) {
                    if (isAvailSymbol(currentEntry)) {
                        // nop
                    } else {
                        qinx = removeQueue(queue, qinx);
                        continue;
                    }
                }

                // 맨 뒤의 독립 기호는 제거
                if (qinx > 0) {
                    prevEntry = queue.get(qinx - 1);
                    if (isAvailSymbol(currentEntry)) {
                        // nop
                    } else if (isEntryType(prevEntry, ALPHA, NUMBER, ALPHANUM, NUMBER_TRANS, SYMBOL)) {
                        // nop
                    } else {
                        qinx = removeQueue(queue, qinx);
                        continue;
                    }
                }

                // 공백에 둘러쌓인 단독 기호는 제거 -> 단독기호는 제거
                if (qinx > 0 && qinx < queue.size()) {
                    if (isAvailSymbol(currentEntry)) {
                        // nop
                    } else {
                        qinx = removeQueue(queue, qinx);
                        continue;
                    }
                }

                if (qinx > 0 && qinx + 1 < queue.size()) {
                    if (isAvailSymbol(currentEntry)) {
                        // nop
                    } else {
                        // 독립 가능한 기호가 아닌 경우에만 처리
                        prevEntry = queue.get(qinx - 1);
                        nextEntry = queue.get(qinx + 1);
                        if (isNotConnected(prevEntry, currentEntry) && isNotConnected(currentEntry, nextEntry)) {
                            qinx = removeQueue(queue, qinx);
                            continue;
                        }
                        // 앞뒤로 모델명 가능성있는 글자들이 아니면 삭제
                        if (isNotModelName(nextEntry, prevEntry)) {
                            qinx = removeQueue(queue, qinx);
                            continue;
                        }
                    }
                }
            }

            // 모델명 엔트리의 경우 처리
            if (isModelNameEntry(currentEntry) && currentEntry.length > 2) {
                if (isEquals(getType(currentEntry.buf[currentEntry.start + currentEntry.length - 1]), SYMBOL)) {
                    currentEntry.length--;
                    currentEntry.endOffset--;
                }
            }

            // 5자리 이상의 독립적인 숫자는 모델명으로 리턴.
            if (isNumberEntry(currentEntry)  && currentEntry.length >= 5) {
                currentEntry.type = MODEL_NAME;
            }

            // 색인시 단위명 규칙에서 단위명을 추가로 뽑아준다
            if(!option.useForQuery()){
                if (currentEntry.type == UNIT_ALPHA) {
                    RuleEntry dummy = currentEntry.clone();

                    // 숫자+단위 한 텀씩 결합할때만..
                    if (currentEntry != null && currentEntry.subEntry.size() < 2) {
                        if (currentEntry != null && currentEntry.subEntry.size() == 1) {
                            RuleEntry number = currentEntry.subEntry.remove(0);
                            currentEntry.start += number.length;
                            currentEntry.length -= number.length;
                            currentEntry.startOffset += number.length;
                            currentEntry.type = ALPHA;
                            addQueue(queue, qinx, number);
                        } else {
                            currentEntry.type = ALPHANUM;
                        }
                        currentEntry.synonym = null;
                        addQueue(queue, qinx, dummy);
                    }
                }
            }
        }

        // 큐의 추가삭제는 없으므로 동시 처리 해 준다.
        syncQueueWithEntry(queue);

        // FULL-TERM 과 나머지 1개 TERM 이 같은 경우
        if (queue.size() > 1 && isFullStringEntry(currentEntry = queue.get(0))
            && (prevEntry = queue.get(1)).startOffset == currentEntry.startOffset && prevEntry.endOffset == currentEntry.endOffset) {
            // 동의어 합치기
            combineSynonym(queue, prevEntry, currentEntry);
        }

        logger.trace("5th process complete / queue:{}", queue);
    }

    private void combineSynonym(List<RuleEntry> queue, RuleEntry prevEntry, RuleEntry currentEntry) {
        if (currentEntry.synonym != null && currentEntry.synonym.length > 0 &&
                prevEntry.synonym != null && prevEntry.synonym.length > 0) {
            int len = prevEntry.synonym.length;
            prevEntry.synonym = Arrays.copyOf(prevEntry.synonym, len + currentEntry.synonym.length);
            System.arraycopy(currentEntry.synonym, 0, prevEntry.synonym, len, currentEntry.synonym.length);
        } else if(currentEntry.synonym != null && currentEntry.synonym.length > 0) {
            prevEntry.synonym = currentEntry.synonym;
        } else {
            // NOP
        }
        queue.remove(0);
    }

    private void syncQueueWithEntry(List<RuleEntry> queue) {
        RuleEntry currentEntry;
        for (RuleEntry ruleEntry : queue) {
            // modifiable 을 특별 용도로 사용한다.
            currentEntry = ruleEntry;

            if (isFullStringEntry(currentEntry)) {
                continue;
            }
            if (currentEntry.subEntry != null && currentEntry.subEntry.size() > 0) {
                logger.trace("subEntry:{}", currentEntry.subEntry);
                currentEntry.modifiable = true;
            } else {
                currentEntry.subEntry = null;
                currentEntry.modifiable = false;
            }

            CharVector token = currentEntry.makeTerm(null);
            if (!option.useForQuery() && existCompoundDict(token)) {
                CharSequence[] compounds = compoundDictionary.get(token);
                for (CharSequence word : compounds) {
                    CharVector cv = CharVector.valueOf(word);
                    RuleEntry entry = new RuleEntry(cv.array(), cv.offset(), cv.length(), currentEntry.startOffset, currentEntry.endOffset, COMPOUND);
                    if (currentEntry.subEntry == null) {
                        currentEntry.subEntry = new ArrayList<>();
                    }
                    currentEntry.subEntry.add(entry);
                }
                if (currentEntry.subEntry != null) {
                    Collections.sort(currentEntry.subEntry);
                }
                currentEntry.type = COMPOUND;
            }
        }
    }

    private boolean existCompoundDict(CharVector token) {
        return compoundDictionary != null && compoundDictionary.containsKey(token);
    }

    private boolean isNotModelName(RuleEntry nextEntry, RuleEntry prevEntry) {
        return isNotEntryType(prevEntry, ALPHA, NUMBER, ALPHANUM, NUMBER_TRANS, SYMBOL)
                || isNotEntryType(nextEntry, ALPHA, NUMBER, ALPHANUM, NUMBER_TRANS, SYMBOL);
    }

    private boolean isHeadIndex(List<RuleEntry> queue, int qinx) {
        return qinx == 0 && qinx + 1 < queue.size();
    }

    private boolean isAvailSymbol(RuleEntry currentEntry) {
        return currentEntry.length == 1 && containsChar(AVAIL_SYMBOLS_STANDALONE, currentEntry.buf[currentEntry.start]);
    }

    private boolean isNotAvailSymbol(RuleEntry currentEntry) {
        // TODO:특수문자가 한꺼번에 많이 들어온 경우 허용되는 특수문자만 가린다.
        return isSymbolEntry(currentEntry) && !containsChar(AVAIL_SYMBOLS, currentEntry.buf[currentEntry.start]);
    }

    private int removeQueue(List<RuleEntry> queue, int qinx) {
        queue.remove(qinx);
        qinx--;
        return qinx;
    }

    private int addQueue(List<RuleEntry> queue, int qinx, RuleEntry entry) {
        queue.add(qinx, entry);
        qinx++;
        return qinx;
    }
}

